### `src/store/cart.ts`

```ts
import create from 'zustand';
import { persist } from 'zustand/middleware';

interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

interface CartState {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
}

export const useCartStore = create<CartState>()(
  persist(
    (set) => ({
      items: [],
      addItem: (item) =>
        set((state) => {
          const existing = state.items.find((i) => i.id === item.id);
          if (existing) {
            return {
              items: state.items.map((i) =>
                i.id === item.id ? { ...i, quantity: i.quantity + item.quantity } : i
              ),
            };
          }
          return { items: [...state.items, item] };
        }),
      removeItem: (id) =>
        set((state) => ({ items: state.items.filter((i) => i.id !== id) })),
      clearCart: () => set({ items: [] }),
    }),
    { name: 'cart-storage' }
  )
);
```

### `src/pages/products/[slug].tsx`

```tsx
import { GetStaticProps, GetStaticPaths } from 'next';
import { useQuery } from '@tanstack/react-query';
import api from '../../lib/api';
import { useCartStore } from '../../store/cart';

export default function ProductPage({ slug }: { slug: string }) {
  const { data: product, isLoading } = useQuery(['product', slug], () =>
    api.get(`/products/${slug}`).then((res) => res.data)
  );
  const addItem = useCartStore((state) => state.addItem);

  if (isLoading) return <p>Loading…</p>;

  return (
    <div className="p-4">
      <h1 className="text-3xl font-bold">{product.title}</h1>
      <img src={product.image} alt={product.title} className="w-full h-auto" />
      <p className="mt-4">{product.description}</p>
      <p className="mt-2 text-xl font-semibold">${product.price}</p>
      <button
        onClick={() => addItem({ id: product.id, name: product.title, price: product.price, quantity: 1 })}
        className="mt-4 bg-blue-600 text-white px-4 py-2 rounded"
      >
        Add to Cart
      </button>
    </div>
  );
}

export const getStaticPaths: GetStaticPaths = async () => {
  const res = await api.get('/products');
  const products = res.data;
  const paths = products.map((p: any) => ({ params: { slug: p.slug } }));
  return { paths, fallback: 'blocking' };
};

export const getStaticProps: GetStaticProps = async ({ params }) => {
  return { props: { slug: params?.slug } };
};
```

