## 5.  Routing & Navigation

| Page | Path | Notes |
|------|------|-------|
| Home | `/` | Landing page, featured products |
| Product List | `/products` | Paginated or infinite scroll |
| Product Detail | `/products/[slug]` | SSG + ISR |
| Cart | `/cart` | Client‑side state, persists in localStorage |
| Checkout | `/checkout` | Protected route (requires login) |
| Order Confirmation | `/order/[id]` | Server‑side rendered for SEO |

> **Tip:** Use `next/link` for client‑side navigation and `next/router` for programmatic navigation.

---

## 6.  Authentication & Authorization

1. **Auth0** (recommended for quick social logins)

   ```ts
   // src/lib/auth0.ts
   import createAuth0Client from '@auth0/auth0-spa-js';

   export const auth0 = createAuth0Client({
     domain: process.env.NEXT_PUBLIC_AUTH0_DOMAIN!,
     client_id: process.env.NEXT_PUBLIC_AUTH0_CLIENT_ID!,
     redirect_uri: window.location.origin,
   });
   ```

2. **Protect routes**

   ```tsx
   // src/components/ProtectedRoute.tsx
   import { useEffect } from 'react';
   import { useRouter } from 'next/router';
   import { useAuth0 } from '@auth0/auth0-react';

   export default function ProtectedRoute({ children }: { children: JSX.Element }) {
     const { isAuthenticated, isLoading } = useAuth0();
     const router = useRouter();

     useEffect(() => {
       if (!isLoading && !isAuthenticated) router.push('/login');
     }, [isLoading, isAuthenticated]);

     if (isLoading || !isAuthenticated) return <p>Loading…</p>;
     return children;
   }
   ```

3. **Checkout flow** – only accessible after login; otherwise redirect to `/login?returnTo=/checkout`.

---

## 7.  Shopping Cart & Checkout

| Feature | Implementation |
|---------|----------------|
| **Add to cart** | `zustand` store (see above) |
| **Persist cart** | `persist` middleware (localStorage) |
| **Cart UI** | Modal or sidebar component |
| **Checkout** | Form with billing/shipping fields, validation (Yup + React Hook Form) |
| **Payment** | Stripe Elements (client‑side) + Stripe API route (server‑side) |
| **Order confirmation** | Server‑side rendered page with order ID |

### Stripe Checkout Example

```tsx
// src/pages/checkout.tsx
import { loadStripe } from '@stripe/stripe-js';
import { useCartStore } from '../store/cart';
import { useRouter } from 'next/router';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export default function Checkout() {
  const cart = useCartStore((s) => s.items);
  const router = useRouter();

  const handleCheckout = async () => {
    const stripe = await stripePromise;
    const res = await fetch('/api/checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: cart }),
    });
    const session = await res.json();
    await stripe?.redirectToCheckout({ sessionId: session.id });
  };

  return (
    <div>
      <h1>Checkout</h1>
      {/* Render cart summary */}
      <button onClick={handleCheckout}>Pay with Stripe</button>
    </div>
  );
}
```

**API Route (`pages/api/checkout.ts`)**

```ts
import { NextApiRequest, NextApiResponse } from 'next';
import Stripe from 'stripe';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { apiVersion: '2024-04-10' });

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();

  const { items } = req.body;
  const line_items = items.map((i: any) => ({
    price_data: {
      currency: 'usd',
      product_data: { name: i.name },
      unit_amount: Math.round(i.price * 100),
    },
    quantity: i.quantity,
  }));

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items,
    mode: 'payment',
    success_url: `${process.env.NEXT_PUBLIC_BASE_URL}/order/${'{CHECKOUT_SESSION_ID}'}`,
    cancel_url: `${process.env.NEXT_PUBLIC_BASE_URL}/checkout`,
  });

  res.json({ id: session.id });
}
```

